def build_add(variant):
    if variant.strip() == "wrong_sum":
        return lambda a, b: a + b + 1
    if variant.strip() == "no_type_error":
        return lambda a, b: str(a) + str(b)

    def add(a, b):
        if isinstance(a, str) or isinstance(b, str):
            raise TypeError("numbers only")
        return a + b

    return add


def run_add_tests(variant="correct"):
    add = build_add(variant)
    results = {}
    for key, fn in (("normal", lambda: add(2, 3) == 5),
                    ("edge", lambda: add(-1, 1) == 0)):
        try:
            results[key] = fn()
        except BaseException:
            results[key] = False
    try:
        add("a", 1)
        results["raises_type_error"] = False
    except TypeError:
        results["raises_type_error"] = True
    except BaseException:
        results["raises_type_error"] = False
    return results
